export type FieldError = string | string[] | undefined;

export function toErrors(error: FieldError): string[] {
  const errors = Array.isArray(error) ? error : [error];
  return errors.filter((message): message is string => !!message);
}

export function joinIds(...ids: Array<string | false | null | undefined>): string | undefined {
  return ids.filter(Boolean).join(' ') || undefined;
}

/** A form control's id (given, or generated by `$props.id()`), its hint and error ids, and its messages. */
export function fieldIds(id: string | null | undefined, uid: string, error: FieldError) {
  const inputId = id ?? uid;
  return {
    inputId,
    hintId: `${inputId}-hint`,
    errorId: `${inputId}-error`,
    errors: toErrors(error),
  };
}
